// MetricsBuilder provides an interface for scrapers to report metrics while taking care of all the transformations
// required to produce metric representation defined in metadata and user config.
type MetricsBuilder struct {
	config                                MetricsBuilderConfig // config of the metrics builder.
	startTime                             pcommon.Timestamp    // start time that will be applied to all recorded data points.
	metricsCapacity                       int                  // maximum observed number of metrics per resource.
	metricsBuffer                         pmetric.Metrics      // accumulates metrics data before emitting.
	buildInfo                             component.BuildInfo  // contains version information.
	resourceAttributeIncludeFilter        map[string]filter.Filter
	resourceAttributeExcludeFilter        map[string]filter.Filter
	metricKvmDomainCPUCount               metricKvmDomainCPUCount
	metricKvmDomainCPUTime                metricKvmDomainCPUTime
	metricKvmDomainDiskErrors             metricKvmDomainDiskErrors
	metricKvmDomainDiskReadBytes          metricKvmDomainDiskReadBytes
	metricKvmDomainDiskReadOperations     metricKvmDomainDiskReadOperations
	metricKvmDomainDiskWriteBytes         metricKvmDomainDiskWriteBytes
	metricKvmDomainDiskWriteOperations    metricKvmDomainDiskWriteOperations
	metricKvmDomainMemoryCurrent          metricKvmDomainMemoryCurrent
	metricKvmDomainMemoryMaximum          metricKvmDomainMemoryMaximum
	metricKvmDomainNetworkReceiveBytes    metricKvmDomainNetworkReceiveBytes
	metricKvmDomainNetworkReceiveDrops    metricKvmDomainNetworkReceiveDrops
	metricKvmDomainNetworkReceiveErrors   metricKvmDomainNetworkReceiveErrors
	metricKvmDomainNetworkReceivePackets  metricKvmDomainNetworkReceivePackets
	metricKvmDomainNetworkTransmitBytes   metricKvmDomainNetworkTransmitBytes
	metricKvmDomainNetworkTransmitDrops   metricKvmDomainNetworkTransmitDrops
	metricKvmDomainNetworkTransmitErrors  metricKvmDomainNetworkTransmitErrors
	metricKvmDomainNetworkTransmitPackets metricKvmDomainNetworkTransmitPackets
	metricKvmDomainState                  metricKvmDomainState
}

// MetricBuilderOption applies changes to default metrics builder.
type MetricBuilderOption interface {
	apply(*MetricsBuilder)
}

type metricBuilderOptionFunc func(mb *MetricsBuilder)

func (mbof metricBuilderOptionFunc) apply(mb *MetricsBuilder) {
	mbof(mb)
}

// WithStartTime sets startTime on the metrics builder.
func WithStartTime(startTime pcommon.Timestamp) MetricBuilderOption {
	return metricBuilderOptionFunc(func(mb *MetricsBuilder) {
		mb.startTime = startTime
	})
}
func NewMetricsBuilder(mbc MetricsBuilderConfig, settings receiver.Settings, options ...MetricBuilderOption) *MetricsBuilder {
	mb := &MetricsBuilder{
		config:                                mbc,
		startTime:                             pcommon.NewTimestampFromTime(time.Now()),
		metricsBuffer:                         pmetric.NewMetrics(),
		buildInfo:                             settings.BuildInfo,
		metricKvmDomainCPUCount:               newMetricKvmDomainCPUCount(mbc.Metrics.KvmDomainCPUCount),
		metricKvmDomainCPUTime:                newMetricKvmDomainCPUTime(mbc.Metrics.KvmDomainCPUTime),
		metricKvmDomainDiskErrors:             newMetricKvmDomainDiskErrors(mbc.Metrics.KvmDomainDiskErrors),
		metricKvmDomainDiskReadBytes:          newMetricKvmDomainDiskReadBytes(mbc.Metrics.KvmDomainDiskReadBytes),
		metricKvmDomainDiskReadOperations:     newMetricKvmDomainDiskReadOperations(mbc.Metrics.KvmDomainDiskReadOperations),
		metricKvmDomainDiskWriteBytes:         newMetricKvmDomainDiskWriteBytes(mbc.Metrics.KvmDomainDiskWriteBytes),
		metricKvmDomainDiskWriteOperations:    newMetricKvmDomainDiskWriteOperations(mbc.Metrics.KvmDomainDiskWriteOperations),
		metricKvmDomainMemoryCurrent:          newMetricKvmDomainMemoryCurrent(mbc.Metrics.KvmDomainMemoryCurrent),
		metricKvmDomainMemoryMaximum:          newMetricKvmDomainMemoryMaximum(mbc.Metrics.KvmDomainMemoryMaximum),
		metricKvmDomainNetworkReceiveBytes:    newMetricKvmDomainNetworkReceiveBytes(mbc.Metrics.KvmDomainNetworkReceiveBytes),
		metricKvmDomainNetworkReceiveDrops:    newMetricKvmDomainNetworkReceiveDrops(mbc.Metrics.KvmDomainNetworkReceiveDrops),
		metricKvmDomainNetworkReceiveErrors:   newMetricKvmDomainNetworkReceiveErrors(mbc.Metrics.KvmDomainNetworkReceiveErrors),
		metricKvmDomainNetworkReceivePackets:  newMetricKvmDomainNetworkReceivePackets(mbc.Metrics.KvmDomainNetworkReceivePackets),
		metricKvmDomainNetworkTransmitBytes:   newMetricKvmDomainNetworkTransmitBytes(mbc.Metrics.KvmDomainNetworkTransmitBytes),
		metricKvmDomainNetworkTransmitDrops:   newMetricKvmDomainNetworkTransmitDrops(mbc.Metrics.KvmDomainNetworkTransmitDrops),
		metricKvmDomainNetworkTransmitErrors:  newMetricKvmDomainNetworkTransmitErrors(mbc.Metrics.KvmDomainNetworkTransmitErrors),
		metricKvmDomainNetworkTransmitPackets: newMetricKvmDomainNetworkTransmitPackets(mbc.Metrics.KvmDomainNetworkTransmitPackets),
		metricKvmDomainState:                  newMetricKvmDomainState(mbc.Metrics.KvmDomainState),
		resourceAttributeIncludeFilter:        make(map[string]filter.Filter),
		resourceAttributeExcludeFilter:        make(map[string]filter.Filter),
	}
	if mbc.ResourceAttributes.KvmDomainName.MetricsInclude != nil {
		mb.resourceAttributeIncludeFilter["kvm.domain.name"] = filter.CreateFilter(mbc.ResourceAttributes.KvmDomainName.MetricsInclude)
	}
	if mbc.ResourceAttributes.KvmDomainName.MetricsExclude != nil {
		mb.resourceAttributeExcludeFilter["kvm.domain.name"] = filter.CreateFilter(mbc.ResourceAttributes.KvmDomainName.MetricsExclude)
	}
	if mbc.ResourceAttributes.KvmDomainUUID.MetricsInclude != nil {
		mb.resourceAttributeIncludeFilter["kvm.domain.uuid"] = filter.CreateFilter(mbc.ResourceAttributes.KvmDomainUUID.MetricsInclude)
	}
	if mbc.ResourceAttributes.KvmDomainUUID.MetricsExclude != nil {
		mb.resourceAttributeExcludeFilter["kvm.domain.uuid"] = filter.CreateFilter(mbc.ResourceAttributes.KvmDomainUUID.MetricsExclude)
	}

	for _, op := range options {
		op.apply(mb)
	}
	return mb
}

// NewResourceBuilder returns a new resource builder that should be used to build a resource associated with for the emitted metrics.
func (mb *MetricsBuilder) NewResourceBuilder() *ResourceBuilder {
	return NewResourceBuilder(mb.config.ResourceAttributes)
}

// updateCapacity updates max length of metrics and resource attributes that will be used for the slice capacity.
func (mb *MetricsBuilder) updateCapacity(rm pmetric.ResourceMetrics) {
	if mb.metricsCapacity < rm.ScopeMetrics().At(0).Metrics().Len() {
		mb.metricsCapacity = rm.ScopeMetrics().At(0).Metrics().Len()
	}
}

// ResourceMetricsOption applies changes to provided resource metrics.
type ResourceMetricsOption interface {
	apply(pmetric.ResourceMetrics)
}

type resourceMetricsOptionFunc func(pmetric.ResourceMetrics)

func (rmof resourceMetricsOptionFunc) apply(rm pmetric.ResourceMetrics) {
	rmof(rm)
}

// WithResource sets the provided resource on the emitted ResourceMetrics.
// It's recommended to use ResourceBuilder to create the resource.
func WithResource(res pcommon.Resource) ResourceMetricsOption {
	return resourceMetricsOptionFunc(func(rm pmetric.ResourceMetrics) {
		res.CopyTo(rm.Resource())
	})
}

// WithStartTimeOverride overrides start time for all the resource metrics data points.
// This option should be only used if different start time has to be set on metrics coming from different resources.
func WithStartTimeOverride(start pcommon.Timestamp) ResourceMetricsOption {
	return resourceMetricsOptionFunc(func(rm pmetric.ResourceMetrics) {
		var dps pmetric.NumberDataPointSlice
		metrics := rm.ScopeMetrics().At(0).Metrics()
		for i := 0; i < metrics.Len(); i++ {
			switch metrics.At(i).Type() {
			case pmetric.MetricTypeGauge:
				dps = metrics.At(i).Gauge().DataPoints()
			case pmetric.MetricTypeSum:
				dps = metrics.At(i).Sum().DataPoints()
			}
			for j := 0; j < dps.Len(); j++ {
				dps.At(j).SetStartTimestamp(start)
			}
		}
	})
}

// EmitForResource saves all the generated metrics under a new resource and updates the internal state to be ready for
// recording another set of data points as part of another resource. This function can be helpful when one scraper
// needs to emit metrics from several resources. Otherwise calling this function is not required,
// just `Emit` function can be called instead.
// Resource attributes should be provided as ResourceMetricsOption arguments.
func (mb *MetricsBuilder) EmitForResource(options ...ResourceMetricsOption) {
	rm := pmetric.NewResourceMetrics()
	ils := rm.ScopeMetrics().AppendEmpty()
	ils.Scope().SetName(ScopeName)
	ils.Scope().SetVersion(mb.buildInfo.Version)
	ils.Metrics().EnsureCapacity(mb.metricsCapacity)
	mb.metricKvmDomainCPUCount.emit(ils.Metrics())
	mb.metricKvmDomainCPUTime.emit(ils.Metrics())
	mb.metricKvmDomainDiskErrors.emit(ils.Metrics())
	mb.metricKvmDomainDiskReadBytes.emit(ils.Metrics())
	mb.metricKvmDomainDiskReadOperations.emit(ils.Metrics())
	mb.metricKvmDomainDiskWriteBytes.emit(ils.Metrics())
	mb.metricKvmDomainDiskWriteOperations.emit(ils.Metrics())
	mb.metricKvmDomainMemoryCurrent.emit(ils.Metrics())
	mb.metricKvmDomainMemoryMaximum.emit(ils.Metrics())
	mb.metricKvmDomainNetworkReceiveBytes.emit(ils.Metrics())
	mb.metricKvmDomainNetworkReceiveDrops.emit(ils.Metrics())
	mb.metricKvmDomainNetworkReceiveErrors.emit(ils.Metrics())
	mb.metricKvmDomainNetworkReceivePackets.emit(ils.Metrics())
	mb.metricKvmDomainNetworkTransmitBytes.emit(ils.Metrics())
	mb.metricKvmDomainNetworkTransmitDrops.emit(ils.Metrics())
	mb.metricKvmDomainNetworkTransmitErrors.emit(ils.Metrics())
	mb.metricKvmDomainNetworkTransmitPackets.emit(ils.Metrics())
	mb.metricKvmDomainState.emit(ils.Metrics())

	for _, op := range options {
		op.apply(rm)
	}
	for attr, filter := range mb.resourceAttributeIncludeFilter {
		if val, ok := rm.Resource().Attributes().Get(attr); ok && !filter.Matches(val.AsString()) {
			return
		}
	}
	for attr, filter := range mb.resourceAttributeExcludeFilter {
		if val, ok := rm.Resource().Attributes().Get(attr); ok && filter.Matches(val.AsString()) {
			return
		}
	}

	if ils.Metrics().Len() > 0 {
		mb.updateCapacity(rm)
		rm.MoveTo(mb.metricsBuffer.ResourceMetrics().AppendEmpty())
	}
}

// Emit returns all the metrics accumulated by the metrics builder and updates the internal state to be ready for
// recording another set of metrics. This function will be responsible for applying all the transformations required to
// produce metric representation defined in metadata and user config, e.g. delta or cumulative.
func (mb *MetricsBuilder) Emit(options ...ResourceMetricsOption) pmetric.Metrics {
	mb.EmitForResource(options...)
	metrics := mb.metricsBuffer
	mb.metricsBuffer = pmetric.NewMetrics()
	return metrics
}

